:root {
  --bg-0: #07080b;
  --bg-1: #0d0f14;
  --bg-2: #14171f;
  --bg-3: #1c2029;
  --line: #262b36;
  --line-strong: #3a4150;
  --text-0: #f5f6f8;
  --text-1: #c5c8d1;
  --text-2: #8a8f9c;
  --text-3: #5b6070;
  --accent: #d4ff3a;
  --accent-ink: #0a0c10;
  --warn: #ff7a3a;
  --danger: #ff4f6b;
  --good: #5ee2a8;
  --radius-s: 8px;
  --radius-m: 14px;
  --radius-l: 22px;
  --shadow-1: 0 1px 0 rgba(255,255,255,0.04) inset, 0 12px 30px -16px rgba(0,0,0,0.7);
  --shadow-2: 0 30px 60px -30px rgba(0,0,0,0.8);
  --font-sans: "Inter", "SF Pro Text", system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  --font-display: "Fraunces", "Playfair Display", "Times New Roman", Georgia, serif;
}

* { box-sizing: border-box; }
html, body { margin: 0; padding: 0; }

body {
  font-family: var(--font-sans);
  background: var(--bg-0);
  color: var(--text-0);
  -webkit-font-smoothing: antialiased;
  text-rendering: optimizeLegibility;
  line-height: 1.45;
  min-height: 100vh;
}

img { max-width: 100%; display: block; }
a { color: inherit; text-decoration: none; }
button { font: inherit; color: inherit; background: none; border: 0; cursor: pointer; }

:focus-visible {
  outline: 2px solid var(--accent);
  outline-offset: 2px;
  border-radius: 6px;
}

.skip-link {
  position: absolute;
  left: -9999px;
  top: 0;
  background: var(--accent);
  color: var(--accent-ink);
  padding: 10px 16px;
  font-weight: 600;
  z-index: 1000;
  border-radius: 0 0 8px 0;
}
.skip-link:focus { left: 0; }

.sr-only {
  position: absolute !important;
  width: 1px; height: 1px;
  padding: 0; margin: -1px;
  overflow: hidden; clip: rect(0,0,0,0);
  white-space: nowrap; border: 0;
}

.shell {
  max-width: 1320px;
  margin: 0 auto;
  padding: 0 28px;
}

/* Announcement bar */
.announce {
  background: linear-gradient(90deg, #0e1118 0%, #181b24 50%, #0e1118 100%);
  border-bottom: 1px solid var(--line);
  font-size: 13px;
  color: var(--text-1);
}
.announce__row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  height: 38px;
  gap: 18px;
}
.announce__msg { display: flex; align-items: center; gap: 10px; }
.announce__dot {
  width: 6px; height: 6px; border-radius: 50%;
  background: var(--accent);
  box-shadow: 0 0 12px var(--accent);
}
.announce__links { display: flex; gap: 22px; }
.announce__links a { color: var(--text-2); }
.announce__links a:hover { color: var(--text-0); }

/* Header */
.header {
  position: sticky;
  top: 0;
  z-index: 50;
  background: rgba(7, 8, 11, 0.82);
  backdrop-filter: saturate(140%) blur(14px);
  -webkit-backdrop-filter: saturate(140%) blur(14px);
  border-bottom: 1px solid var(--line);
}
.header__row {
  display: grid;
  grid-template-columns: auto 1fr auto;
  align-items: center;
  height: 72px;
  gap: 28px;
}
.brand {
  display: flex;
  align-items: center;
  gap: 10px;
  font-family: var(--font-display);
  font-weight: 600;
  letter-spacing: 0.02em;
  font-size: 22px;
}
.brand__mark {
  width: 30px; height: 30px;
  border-radius: 8px;
  background: linear-gradient(135deg, var(--accent), #7ad13d 70%);
  display: grid; place-items: center;
  color: var(--accent-ink);
  font-weight: 800;
  font-family: var(--font-sans);
  font-size: 14px;
}
.nav__list {
  list-style: none;
  margin: 0; padding: 0;
  display: flex;
  gap: 6px;
  justify-content: center;
}
.nav__link {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  padding: 8px 14px;
  border-radius: 999px;
  color: var(--text-1);
  font-size: 14px;
  font-weight: 500;
  transition: background .2s, color .2s;
}
.nav__link:hover { background: var(--bg-2); color: var(--text-0); }
.nav__link[aria-current="page"] {
