  color: var(--text-0);
}
.nav__badge {
  font-size: 10px;
  font-weight: 700;
  background: var(--accent);
  color: var(--accent-ink);
  padding: 2px 6px;
  border-radius: 999px;
  letter-spacing: 0.04em;
}

.actions { display: flex; align-items: center; gap: 6px; }
.icon-btn {
  position: relative;
  width: 40px; height: 40px;
  display: grid; place-items: center;
  border-radius: 10px;
  color: var(--text-1);
  transition: background .2s, color .2s;
}
.icon-btn:hover { background: var(--bg-2); color: var(--text-0); }
.icon-btn__count {
  position: absolute;
  top: 6px; right: 4px;
  min-width: 18px; height: 18px;
  background: var(--accent);
  color: var(--accent-ink);
  font-size: 11px;
  font-weight: 700;
  border-radius: 9px;
  padding: 0 5px;
  display: grid; place-items: center;
  border: 2px solid var(--bg-0);
}
.search-pill {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  background: var(--bg-2);
  border: 1px solid var(--line);
  border-radius: 999px;
  padding: 8px 14px;
  color: var(--text-2);
  font-size: 13px;
  min-width: 240px;
}
.search-pill kbd {
  margin-left: auto;
  font-family: var(--font-sans);
  font-size: 11px;
  background: var(--bg-3);
  border: 1px solid var(--line);
  border-radius: 4px;
  padding: 1px 5px;
  color: var(--text-2);
}
.search-pill:hover { border-color: var(--line-strong); color: var(--text-1); }

/* Hero */
.hero {
  padding: 36px 0 64px;
}
.hero__grid {
  display: grid;
  grid-template-columns: 1.15fr 1fr;
  gap: 28px;
  align-items: stretch;
}
.hero__main {
  position: relative;
  border-radius: var(--radius-l);
  background:
    radial-gradient(80% 60% at 80% 10%, rgba(212,255,58,0.16), transparent 60%),
    linear-gradient(180deg, #11141b 0%, #0a0c11 100%);
  border: 1px solid var(--line);
  overflow: hidden;
  padding: 56px 56px 48px;
  display: flex;
  flex-direction: column;
  justify-content: space-between;
  min-height: 540px;
  isolation: isolate;
}
.hero__main::after {
  content: "";
  position: absolute;
  inset: 0;
  background-image:
    radial-gradient(rgba(255,255,255,0.05) 1px, transparent 1px);
  background-size: 22px 22px;
  mask-image: radial-gradient(60% 80% at 70% 30%, black, transparent 70%);
  pointer-events: none;
  z-index: -1;
}
.hero__eyebrow {
  display: inline-flex;
  align-items: center;
  gap: 10px;
  font-size: 12px;
  letter-spacing: 0.18em;
  text-transform: uppercase;
  color: var(--text-2);
  font-weight: 600;
}
.hero__eyebrow::before {
  content: "";
  width: 28px; height: 1px;
  background: var(--text-3);
}
.hero__title {
  font-family: var(--font-display);
  font-weight: 500;
  font-size: clamp(40px, 5.4vw, 76px);
  line-height: 1.02;
  letter-spacing: -0.02em;
  margin: 22px 0 0;
}
.hero__title em {
  font-style: italic;
  color: var(--accent);
  font-weight: 400;
}
.hero__sub {
  margin-top: 22px;
  max-width: 480px;
  color: var(--text-1);
  font-size: 16px;
}
.hero__cta {
  display: flex;
  gap: 12px;
  margin-top: 32px;
  flex-wrap: wrap;
}
.btn {
  display: inline-flex;
  align-items: center;
  gap: 10px;
  padding: 14px 22px;
  border-radius: 999px;
  font-weight: 600;
  font-size: 14px;
  letter-spacing: 0.01em;
  border: 1px solid transparent;
  transition: transform .15s, background .2s, border-color .2s, color .2s;
}
.btn:hover { transform: translateY(-1px); }
.btn--primary {
  background: var(--accent);
  color: var(--accent-ink);
