  border-bottom: 1px solid var(--line);
}
.header__row {
  display: grid;
  grid-template-columns: auto 1fr auto;
  align-items: center;
  height: 72px;
  gap: 28px;
}
.brand {
  display: flex;
  align-items: center;
  gap: 10px;
  font-family: var(--font-display);
  font-weight: 600;
  letter-spacing: 0.02em;
  font-size: 22px;
}
.brand__mark {
  width: 30px; height: 30px;
  border-radius: 8px;
  background: linear-gradient(135deg, var(--accent), #7ad13d 70%);
  display: grid; place-items: center;
  color: var(--accent-ink);
  font-weight: 800;
  font-family: var(--font-sans);
  font-size: 14px;
}
.nav__list {
  list-style: none;
  margin: 0; padding: 0;
  display: flex;
  gap: 6px;
  justify-content: center;
}
.nav__link {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  padding: 8px 14px;
  border-radius: 999px;
  color: var(--text-1);
  font-size: 14px;
  font-weight: 500;
  transition: background .2s, color .2s;
}
.nav__link:hover { background: var(--bg-2); color: var(--text-0); }
.nav__link[aria-current="page"] {
  background: var(--bg-2);
  color: var(--text-0);
}
.nav__badge {
  font-size: 10px;
  font-weight: 700;
  background: var(--accent);
  color: var(--accent-ink);
  padding: 2px 6px;
  border-radius: 999px;
  letter-spacing: 0.04em;
}

.actions { display: flex; align-items: center; gap: 6px; }
.icon-btn {
  position: relative;
  width: 40px; height: 40px;
  display: grid; place-items: center;
  border-radius: 10px;
  color: var(--text-1);
  transition: background .2s, color .2s;
}
.icon-btn:hover { background: var(--bg-2); color: var(--text-0); }
.icon-btn__count {
  position: absolute;
  top: 6px; right: 4px;
  min-width: 18px; height: 18px;
  background: var(--accent);
  color: var(--accent-ink);
  font-size: 11px;
  font-weight: 700;
  border-radius: 9px;
  padding: 0 5px;
  display: grid; place-items: center;
  border: 2px solid var(--bg-0);
}
.search-pill {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  background: var(--bg-2);
  border: 1px solid var(--line);
  border-radius: 999px;
  padding: 8px 14px;
  color: var(--text-2);
  font-size: 13px;
  min-width: 240px;
}
.search-pill kbd {
  margin-left: auto;
  font-family: var(--font-sans);
  font-size: 11px;
  background: var(--bg-3);
  border: 1px solid var(--line);
  border-radius: 4px;
  padding: 1px 5px;
  color: var(--text-2);
}
.search-pill:hover { border-color: var(--line-strong); color: var(--text-1); }

/* Hero */
.hero {
  padding: 36px 0 64px;
}
.hero__grid {
  display: grid;
  grid-template-columns: 1.15fr 1fr;
  gap: 28px;
  align-items: stretch;
}
.hero__main {
  position: relative;
  border-radius: var(--radius-l);
  background:
    radial-gradient(80% 60% at 80% 10%, rgba(212,255,58,0.16), transparent 60%),
    linear-gradient(180deg, #11141b 0%, #0a0c11 100%);
  border: 1px solid var(--line);
  overflow: hidden;
  padding: 56px 56px 48px;
  display: flex;
  flex-direction: column;
  justify-content: space-between;
  min-height: 540px;
  isolation: isolate;
}
.hero__main::after {
  content: "";
  position: absolute;
  inset: 0;
  background-image:
    radial-gradient(rgba(255,255,255,0.05) 1px, transparent 1px);
  background-size: 22px 22px;
  mask-image: radial-gradient(60% 80% at 70% 30%, black, transparent 70%);
  pointer-events: none;
  z-index: -1;
}
.hero__eyebrow {
  display: inline-flex;
  align-items: center;
  gap: 10px;
  font-size: 12px;
  letter-spacing: 0.18em;
  text-transform: uppercase;
  color: var(--text-2);
  font-weight: 600;
}
.hero__eyebrow::before {
  content: "";
  width: 28px; height: 1px;
  background: var(--text-3);
}
.hero__title {
  font-family: var(--font-display);
  font-weight: 500;
  font-size: clamp(40px, 5.4vw, 76px);
  line-height: 1.02;
  letter-spacing: -0.02em;
  margin: 22px 0 0;
}
.hero__title em {
  font-style: italic;
  color: var(--accent);
  font-weight: 400;
}
.hero__sub {
  margin-top: 22px;
  max-width: 480px;
  color: var(--text-1);
  font-size: 16px;
}
.hero__cta {
  display: flex;
  gap: 12px;
  margin-top: 32px;
  flex-wrap: wrap;
}
.btn {
  display: inline-flex;
  align-items: center;
  gap: 10px;
  padding: 14px 22px;
  border-radius: 999px;
  font-weight: 600;
  font-size: 14px;
  letter-spacing: 0.01em;
  border: 1px solid transparent;
  transition: transform .15s, background .2s, border-color .2s, color .2s;
}
.btn:hover { transform: translateY(-1px); }
.btn--primary {
  background: var(--accent);
  color: var(--accent-ink);
}
.btn--primary:hover { background: #e2ff63; }
.btn--ghost {
  border-color: var(--line-strong);
  color: var(--text-0);
}
.btn--ghost:hover { background: var(--bg-2); }

.hero__meta {
  margin-top: 48px;
  display: grid;
  grid-template-columns: repeat(3, minmax(0,1fr));
  gap: 18px;
  border-top: 1px solid var(--line);
  padding-top: 28px;
}
.hero__metric {
  display: flex; flex-direction: column; gap: 4px;
}
.hero__metric strong {
  font-family: var(--font-display);
  font-size: 28px;
  font-weight: 500;
}
.hero__metric span { color: var(--text-2); font-size: 13px; }

.hero__side {
  display: grid;
  grid-template-rows: 1.4fr 1fr;
  gap: 20px;
}
.hero-card {
  position: relative;
  border-radius: var(--radius-l);
  border: 1px solid var(--line);
  overflow: hidden;
  padding: 26px;
  display: flex;
  flex-direction: column;
  justify-content: space-between;
  min-height: 220px;
  isolation: isolate;
}
.hero-card--feature {
  background:
    linear-gradient(180deg, rgba(0,0,0,0) 30%, rgba(0,0,0,0.7) 100%),
    radial-gradient(120% 80% at 70% 20%, #2b2438, #0d1018 70%);
}
.hero-card--feature::before {
  content: "";
  position: absolute;
  inset: 0;
  background:
    conic-gradient(from 200deg at 80% 90%, rgba(212,255,58,0.18), transparent 40%),
    radial-gradient(60% 60% at 30% 30%, rgba(120,90,230,0.35), transparent 70%);
  z-index: -1;
}
.hero-card--split {
  background: linear-gradient(180deg, #161a23, #0c0f15);
  display: grid;
  grid-template-columns: 1fr 1fr;
  padding: 0;
}
.hero-card__body {
  padding: 26px;
  display: flex;
  flex-direction: column;
  justify-content: space-between;
}
.hero-card__art {
  background:
    linear-gradient(135deg, #2a2f3d 0%, #141821 100%);
  position: relative;
  overflow: hidden;
}
.hero-card__art::before, .hero-card__art::after {
  content: "";
  position: absolute;
  border-radius: 50%;
  filter: blur(20px);
}
.hero-card__art::before {
  width: 180px; height: 180px;
  background: rgba(212,255,58,0.35);
  top: -40px; right: -40px;
}
.hero-card__art::after {
  width: 140px; height: 140px;
  background: rgba(120,90,230,0.45);
  bottom: -50px; left: -30px;
}
.tag {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  padding: 5px 10px;
  border-radius: 999px;
  background: rgba(255,255,255,0.06);
  border: 1px solid rgba(255,255,255,0.08);
  color: var(--text-1);
}
.tag--accent {
  background: var(--accent);
  color: var(--accent-ink);
  border-color: transparent;
}
.tag--danger {
  background: rgba(255, 79, 107, 0.12);
  color: var(--danger);
  border-color: rgba(255, 79, 107, 0.25);
}
.hero-card h3 {
  font-family: var(--font-display);
  margin: 14px 0 6px;
  font-size: 26px;
  font-weight: 500;
  line-height: 1.1;
  letter-spacing: -0.01em;
}
.hero-card p {
  margin: 0;
  color: var(--text-2);
  font-size: 13px;
}
.hero-card__link {
  margin-top: 18px;
  align-self: flex-start;
  font-size: 13px;
  font-weight: 600;
  color: var(--accent);
  display: inline-flex;
  align-items: center;
  gap: 6px;
}
.hero-card__link:hover { gap: 10px; }

/* Marquee / press strip */
.press {
  border-top: 1px solid var(--line);
  border-bottom: 1px solid var(--line);
  padding: 22px 0;
  background: var(--bg-1);
}
.press__row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 24px;
  flex-wrap: wrap;
}
.press__label {
  font-size: 12px;
  letter-spacing: 0.18em;
  text-transform: uppercase;
  color: var(--text-3);
}
.press__logos {
  display: flex;
  gap: 36px;
  align-items: center;
  flex-wrap: wrap;
  color: var(--text-2);
  font-family: var(--font-display);
  font-size: 18px;
  font-weight: 500;
  letter-spacing: 0.05em;
}
.press__logos span { opacity: 0.7; transition: opacity .2s; }
.press__logos span:hover { opacity: 1; color: var(--text-0); }

/* Section primitives */
.section { padding: 88px 0; }
.section__head {
  display: flex;
  align-items: flex-end;
  justify-content: space-between;
  margin-bottom: 36px;
  gap: 24px;
  flex-wrap: wrap;
}
.section__title {
  font-family: var(--font-display);
  font-weight: 500;
  font-size: clamp(28px, 3vw, 42px);
  letter-spacing: -0.01em;
  margin: 0;
  line-height: 1.1;
}
.section__title em { font-style: italic; color: var(--accent); }
.section__lede {
  margin: 10px 0 0;
  color: var(--text-2);
  max-width: 520px;
  font-size: 15px;
}
.section__actions { display: flex; align-items: center; gap: 8px; }
.chip-row {
  display: flex;
  gap: 8px;
  flex-wrap: wrap;
}
.chip {
  font-size: 13px;
  font-weight: 500;
  padding: 8px 14px;
  border-radius: 999px;
  border: 1px solid var(--line);
  color: var(--text-1);
  background: transparent;
  transition: background .2s, border-color .2s, color .2s;
}
.chip:hover { border-color: var(--line-strong); color: var(--text-0); }
.chip[aria-pressed="true"] {
  background: var(--text-0);
  color: var(--bg-0);
  border-color: var(--text-0);
}

/* Featured products grid */
.products {
  display: grid;
  grid-template-columns: repeat(4, minmax(0,1fr));
  gap: 22px;
}
.product {
  display: flex;
  flex-direction: column;
  gap: 14px;
  background: var(--bg-1);
  border: 1px solid var(--line);
  border-radius: var(--radius-m);
  padding: 14px;
  transition: border-color .2s, transform .2s, background .2s;
}
.product:hover {
  border-color: var(--line-strong);
  background: var(--bg-2);
  transform: translateY(-3px);
}
.product__media {
  position: relative;
  border-radius: 10px;
  overflow: hidden;
  aspect-ratio: 4/5;
  background: #1a1d26;
}
.product__art {
  position: absolute; inset: 0;
}
.product__overlay {
  position: absolute;
  inset: 0;
  display: flex;
  flex-direction: column;
  justify-content: space-between;
  padding: 12px;
}
.product__overlay-top {
  display: flex;
  justify-content: space-between;
  align-items: flex-start;
  gap: 8px;
}
.product__fav {
  width: 34px; height: 34px;
  border-radius: 50%;
  background: rgba(7,8,11,0.7);
  backdrop-filter: blur(10px);
  border: 1px solid rgba(255,255,255,0.08);
  display: grid; place-items: center;
  color: var(--text-1);
  transition: color .2s, background .2s;
}
.product__fav:hover { color: var(--danger); background: rgba(7,8,11,0.9); }
.product__fav[aria-pressed="true"] { color: var(--danger); }
.product__quick {
  align-self: stretch;
  text-align: center;
  background: var(--text-0);
  color: var(--bg-0);
  border-radius: 999px;
  padding: 10px;
  font-size: 13px;
  font-weight: 600;
  opacity: 0;
  transform: translateY(8px);
  transition: opacity .2s, transform .2s;
}
.product:hover .product__quick { opacity: 1; transform: translateY(0); }

.product__info {
  display: flex;
  flex-direction: column;
  gap: 4px;
  padding: 4px 6px 8px;
}
.product__brand {
  font-size: 11px;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  color: var(--text-3);
}
.product__name {
  font-size: 15px;
  font-weight: 500;
  color: var(--text-0);
  line-height: 1.3;
  margin: 0;
}
.product__row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-top: 6px;
  gap: 8px;
}
.product__price {
  display: flex;
  align-items: baseline;
  gap: 8px;
}
.product__price strong {
  font-family: var(--font-display);
  font-size: 18px;
  font-weight: 500;
  color: var(--text-0);
}
.product__price del {
  color: var(--text-3);
  font-size: 13px;
}
.product__rating {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  font-size: 12px;
  color: var(--text-2);
}
.product__rating svg { color: var(--accent); }
.product__swatches {
  display: flex;
  gap: 6px;
  margin-top: 6px;
}
.swatch {
  width: 14px; height: 14px;
  border-radius: 50%;
  border: 1px solid rgba(255,255,255,0.12);
}

/* Deals */
.deals {
  background:
    radial-gradient(50% 60% at 80% 0%, rgba(120,90,230,0.16), transparent 70%),
    linear-gradient(180deg, var(--bg-0), #0a0d14);
  border-top: 1px solid var(--line);
  border-bottom: 1px solid var(--line);
}
.deals__grid {
  display: grid;
  grid-template-columns: 1.2fr 1fr 1fr;
  grid-template-rows: auto auto;
  gap: 22px;
}
.deal {
  position: relative;
  border-radius: var(--radius-l);
  overflow: hidden;
  border: 1px solid var(--line);
  padding: 30px;
  display: flex;
  flex-direction: column;
  justify-content: space-between;
  min-height: 280px;
  isolation: isolate;
  transition: border-color .2s, transform .2s;
}
.deal:hover { border-color: var(--line-strong); transform: translateY(-2px); }
.deal--hero {
  grid-column: span 1;
  grid-row: span 2;
  min-height: 580px;
  background:
    radial-gradient(60% 50% at 80% 80%, rgba(212,255,58,0.25), transparent 70%),
    linear-gradient(180deg, #1a1f2c 0%, #0c0f17 100%);
}
.deal--hero::after {
  content: "";
  position: absolute;
  inset: 0;
  background:
    repeating-linear-gradient(45deg, rgba(255,255,255,0.025) 0 1px, transparent 1px 14px);
  pointer-events: none;
  z-index: -1;
}
.deal--accent {
  background:
    linear-gradient(135deg, #d4ff3a 0%, #99cc2e 100%);
  color: var(--accent-ink);
  border-color: transparent;
}
.deal--accent .deal__price-old { color: rgba(10,12,16,0.45); }
.deal--purple {
  background: linear-gradient(180deg, #251c43 0%, #110b22 100%);
}
.deal--steel {
  background: linear-gradient(180deg, #1d242e 0%, #0e131a 100%);
}
.deal--ember {
  background: linear-gradient(180deg, #2a1718 0%, #150a0c 100%);
}
.deal__eyebrow {
  font-size: 11px;
  letter-spacing: 0.18em;
  text-transform: uppercase;
  font-weight: 700;
  opacity: 0.85;
}
.deal h3 {
  font-family: var(--font-display);
  margin: 14px 0 8px;
  font-size: 30px;
  line-height: 1.05;
  font-weight: 500;
  letter-spacing: -0.01em;
}
.deal--hero h3 { font-size: 44px; }
.deal p {
  margin: 0;
  font-size: 14px;
  opacity: 0.8;
  max-width: 360px;
}
.deal__price {
  display: flex;
  align-items: baseline;
  gap: 10px;
  margin: 16px 0 0;
  font-family: var(--font-display);
}
.deal__price strong { font-size: 28px; font-weight: 500; }
.deal__price-old { text-decoration: line-through; opacity: 0.5; font-size: 16px; }
.deal__footer {
  margin-top: 22px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 14px;
}
.countdown {
  display: flex;
  gap: 6px;
}
.countdown__cell {
  background: rgba(0,0,0,0.35);
  color: inherit;
  border-radius: 8px;
  padding: 8px 10px;
  text-align: center;
  min-width: 48px;
  border: 1px solid rgba(255,255,255,0.08);
}
.deal--accent .countdown__cell { background: rgba(10,12,16,0.15); border-color: rgba(10,12,16,0.18); }
.countdown__num {
  font-family: var(--font-display);
  font-size: 20px;
  font-weight: 500;
  display: block;
  line-height: 1;
}
.countdown__label {
  font-size: 9px;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  opacity: 0.7;
  margin-top: 4px;
  display: block;
}
.deal__btn {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  padding: 11px 18px;
  border-radius: 999px;
  font-weight: 600;
  font-size: 13px;
  background: rgba(255,255,255,0.08);
  border: 1px solid rgba(255,255,255,0.12);
  color: inherit;
  transition: background .2s;
}
.deal--accent .deal__btn {
  background: var(--accent-ink);
  color: var(--accent);
  border-color: transparent;
}
.deal__btn:hover { background: rgba(255,255,255,0.16); }
.deal--accent .deal__btn:hover { background: #1a1d26; }

/* Editorial */
.editorial {
  display: grid;
  grid-template-columns: 1.15fr 1fr;
  gap: 28px;
}
.editorial__feature {
  position: relative;
  border-radius: var(--radius-l);
  overflow: hidden;
  border: 1px solid var(--line);
  background: linear-gradient(180deg, #161b25 0%, #0a0d13 100%);
  min-height: 540px;
  padding: 40px;
  display: flex;
  flex-direction: column;
  justify-content: flex-end;
  isolation: isolate;
}
.editorial__feature::before {
  content: "";
  position: absolute;
  inset: 0;
  background:
    radial-gradient(50% 50% at 30% 30%, rgba(212,255,58,0.18), transparent 70%),
    radial-gradient(60% 60% at 80% 70%, rgba(120,90,230,0.25), transparent 70%);
  z-index: -1;
}
.editorial__feature::after {
  content: "";
  position: absolute;
  inset: 0;
  background:
    linear-gradient(180deg, transparent 50%, rgba(0,0,0,0.6) 100%);
  z-index: -1;
}
.editorial__meta {
  display: flex;
  align-items: center;
  gap: 14px;
  font-size: 12px;
  color: var(--text-2);
  letter-spacing: 0.06em;
}
.editorial__meta::before {
  content: "";
  width: 32px; height: 1px; background: var(--text-3);
}
.editorial__feature h3 {
  font-family: var(--font-display);
  font-size: clamp(32px, 3.4vw, 48px);
  font-weight: 500;
  line-height: 1.1;
  letter-spacing: -0.015em;
  margin: 18px 0 16px;
  max-width: 520px;
}
.editorial__feature p {
  margin: 0;
  color: var(--text-1);
  max-width: 520px;
  font-size: 15px;
}
.editorial__author {
  display: flex; align-items: center; gap: 12px;
  margin-top: 28px;
}
.editorial__avatar {
  width: 40px; height: 40px;
  border-radius: 50%;
  background: linear-gradient(135deg, #cfa, #492);
  display: grid; place-items: center;
  font-weight: 700;
  color: var(--accent-ink);
}
.editorial__author-meta { font-size: 13px; color: var(--text-2); }
.editorial__author-meta strong { color: var(--text-0); display: block; font-weight: 500; }

.editorial__list { display: flex; flex-direction: column; gap: 18px; }
.story {
  display: grid;
  grid-template-columns: 140px 1fr;
  gap: 20px;
  padding: 18px;
  background: var(--bg-1);
  border: 1px solid var(--line);
  border-radius: var(--radius-m);
  transition: border-color .2s, background .2s, transform .2s;
}
.story:hover {
  border-color: var(--line-strong);
  background: var(--bg-2);
  transform: translateX(2px);
}
.story__thumb {
  height: 140px;
  border-radius: 10px;
  position: relative;
  overflow: hidden;
}
.story__thumb--a {
  background:
    linear-gradient(135deg, #d4ff3a, #4a7a0f);
}
.story__thumb--b {
  background:
    linear-gradient(135deg, #6b4ae8, #1a1145);
}
.story__thumb--c {
  background:
    linear-gradient(135deg, #ff7a3a, #5a1408);
}
.story__thumb::after {
  content: "";
  position: absolute;
