    if (filter === 'New arrivals') return PRODUCTS.filter(p => p.tag === 'New' || p.tag === 'Limited');
    if (filter === 'Garments') return PRODUCTS.filter(p => !p.brand.includes('Object'));
    return PRODUCTS;
  }, [filter]);

