/* ---------- Deals ---------- */
const Countdown = ({ target }) => {
  const [now, setNow] = useState(Date.now());
  useEffect(() => {
    const t = setInterval(() => setNow(Date.now()), 1000);
    return () => clearInterval(t);
  }, []);
  const diff = Math.max(0, target - now);
  const d = Math.floor(diff / 86400000);
  const hh = Math.floor((diff % 86400000) / 3600000);
  const mm = Math.floor((diff % 3600000) / 60000);
  const ss = Math.floor((diff % 60000) / 1000);
  const cells = [['Days', d], ['Hrs', hh], ['Min', mm], ['Sec', ss]];
  return h('div', { className: 'countdown', 'aria-label': `Ends in ${d} days ${hh} hours ${mm} minutes` },
    cells.map(([label, n]) => h('div', { key: label, className: 'countdown__cell' },
      h('span', { className: 'countdown__num' }, String(n).padStart(2, '0')),
      h('span', { className: 'countdown__label' }, label)
    ))
  );
};

