const App = () => {
  const [cart, setCart] = useState(2);
  const [fav, setFav] = useState(() => new Set([3]));
  const onAdd = useCallback(() => setCart(c => c + 1), []);
  const onFav = useCallback((id) => {
    setFav(prev => {
      const next = new Set(prev);
      next.has(id) ? next.delete(id) : next.add(id);
      return next;
    });
  }, []);

  return h(Fragment, null,
    h('a', { className: 'skip-link', href: '#main' }, 'Skip to main content'),
    h(Announcement),
    h(Header, { cart, wish: fav.size }),
    h('main', { id: 'main' },
